protocol LayerObject {                   // the layer's declared type
    var id: Int64 { get }
    func describe() -> String
}
extension LayerObject {                  // shared implementation for every member
    func auditTag() -> String { "obj-\(id): \(describe())" }
}
struct User: LayerObject {               // structs can join the layer
    let id: Int64
    func describe() -> String { "user \(id)" }
}
